text = open(SPEC, encoding="utf-8").read()
h0 = hashlib.sha256(text.encode()).hexdigest()
work = text
md = [f"SPEC.md SHA-256 at read: {h0}\n"]
bad = 0
for tag, where, start, end, new in AM:
    n = work.count(start)
    s = work.find(start)
    if n != 1 or s < 0:
        print(f"{tag}: start marker found {n} times -- FAIL"); bad += 1; continue
    if end is EOL:
        e = work.find("\n", s)
    else:
        e = work.find(end, s)
        if e < 0: print(f"{tag}: end marker not found -- FAIL"); bad += 1; continue
        e += len(end)
    old = work[s:e]
    if new is None: new = old + "\n" + P9L
    if work.count(old) != 1: print(f"{tag}: OLD not unique -- FAIL"); bad += 1; continue
    work = work[:s] + new + work[e:]
    md.append(f"### {tag} — {where}\n\nOLD:\n\n```\n{old}\n```\n\nNEW:\n\n```\n{new}\n```\n")
    print(f"{tag}: OK ({len(old)} -> {len(new)} chars)")
open(COPY, "w", encoding="utf-8").write(work)
open(OUT_MD, "w", encoding="utf-8").write("\n".join(md))
lint = [w for w in ("clearly", "obviously", "easy to see", "well known", "well-known") if w in work.lower()]
print("failures:", bad, "| lint hits in amended copy:", lint, "| amended copy:", COPY,
      "sha256", hashlib.sha256(work.encode()).hexdigest(), "| lines", work.count("\n"))
